-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 5 notable NPCs are in' AS assertion, count(*) AS got, 5 AS want
  FROM notable_npcs WHERE slug IN ('prince-onra-misvina', 'sgt-samantha', 'xavier-stuart', 'cana-the-blind', 'high-father-suthue');
SELECT 'and the notables 19' AS assertion, count(*) AS got, 19 AS want
  FROM stat_attacks WHERE owner_kind = 'notable_npc' AND owner_slug IN ('prince-onra-misvina', 'sgt-samantha', 'xavier-stuart', 'cana-the-blind', 'high-father-suthue');

