INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES
('prince-onra-misvina', 'Prince Onra Misvina', 'Onra Misvina, of House Libson, clan Bagh-Dach', 'Commander of the Arzno Mercenary Corps', 'rifts', 'True Atlantean', '12th level Merc Soldier (Point Man/Scout)', 12, 'Scrupulous', '126; looks to be in his late twenties', '6 feet, 5 inches (2.0 m)', '260 lbs (117 kg)', '{"IQ":19,"ME":19,"MA":17,"PS":26,"PP":19,"PE":23,"PB":19,"Spd":31}', 54, 94, NULL, 113, NULL, NULL, NULL, '{"attacks":8,"initiative":2,"strike":4,"parry":10,"dodge":10,"pull":3,"roll":5,"entangle":2,"disarm":4,"damage":15}', 'Hand to Hand: Martial Arts, with Boxing, Fencing and Kick Boxing. Body flip/throw, all hand strikes, all foot strikes including leap kick (plus roundhouse kick, axe kick and knee strike), paired weapons, all holds, back flip, back flip escape and back flip attack. Critical strike on an unmodified 18-20; knockout/stun on an unmodified 20. +1 to strike and parry with a sword or dagger, +1D6 damage with a sword. +2 to save vs psionics/insanity, +16% to save vs coma/death, +4 vs poison, +6 vs magic, +4 vs Horror Factor; 45% trust/intimidate, 45% charm/impress. Skill figures already include +5% to all skills. Male. Rank: Commander. I.S.P.: not applicable.', '[{"name":"Language: Atlantean/Greek","pct":98},{"name":"Language: American","pct":98},{"name":"Language: Dragonese/Elven","pct":90},{"name":"Literacy: Atlantean/Greek","pct":98},{"name":"Literacy: American","pct":90},{"name":"Literacy: Dragonese/Elven","pct":90},{"name":"Detect Ambush","pct":98},{"name":"Detect Concealment","pct":95},{"name":"Intelligence","pct":96},{"name":"Land Navigation","pct":98},{"name":"Prowl","pct":98},{"name":"Surveillance","pct":98},{"name":"Wilderness Survival","pct":98},{"name":"Climbing","pct":98},{"name":"Computer Operation","pct":98},{"name":"Mathematics: Basic","pct":98},{"name":"Military Etiquette","pct":98},{"name":"Radio: Basic","pct":98},{"name":"Sign Language (Military)","pct":90},{"name":"Lore: Demons & Monsters","pct":80},{"name":"Law","pct":55},{"name":"Pilot: Hover Craft (Ground)","pct":98},{"name":"Swimming","pct":98},{"name":"First Aid","pct":90},{"name":"Horsemanship: Exotic","pct":75},{"name":"Language: Spanish","pct":67},{"name":"Literacy: Spanish","pct":55},{"name":"Pilot: Automobile","pct":65}]', 'Athletics (General), Running, Fencing, Boxing and Kick Boxing. W.P. Knife, W.P. Sword, W.P. Energy Pistol and W.P. Energy Rifle at 12th level; W.P. Handguns at 1st level. Climbing is printed 98%/98% and Horsemanship: Exotic 75%/65%. The book files the six language and literacy skills as R.C.C. skills and Detect Ambush through Wilderness Survival as M.O.S. skills.', 'The True Atlantean package: Marks of Heritage and other magic tattoos, P.P.E. recovered at 10 an hour of sleep or 15 an hour of meditation, immune to physical transformation of any kind, keeps growing as an adult, senses vampires within 1,000 feet (305 m), recognizes a vampire on sight (98%), operates dimensional pyramids (90%). Senses ley lines within 120 miles (192 km), 90% to locate; ley line nexuses 98% to locate; the opening of a Rift within 160 miles (256 km); ley line phasing 4 times an hour, up to 16 a day, as a Ley Line Walker. Has arms-dealer and mercenary contacts in the Colorado Baronies, Lazlo and the Magic Zone, and across the Three Galaxies.', 'True Atlantean magic understanding and tattoo lore. Tattoos: Sword covered in Flames (10), Heart Pierced by a Wooden Stake (15), Simple Weapon: Wooden Sword (2), Simple Weapon: Silver Knife (2).', 'None.', NULL, NULL, 'The Pyrus Blade, the house of Libson''s heirloom broadsword: 4D6 S.D.C., or 4D6 M.D. against Mega-Damage foes; against vampires and Splugorth minions it bursts into flame for double damage (8D6), which harms the fire-immune but not the magic-immune; 3 feet (0.9 m) long. A TW-converted NG-LP25 Laser Pulse Submachine-Gun (2D6+1 M.D. single shot or 5D6 triple pulse, 1,000 feet (305 m), 10 shots per 7 P.P.E.). NG-P7 Particle Beam Rifle (2D4x10 M.D., 1,200 feet (365 m), 10 shots a long E-Clip, with 4 spare). TW Exterminator Armor, personalized with an extra-heavy force field: Main Body 100, Arms 40 each, Legs 50 each, Head/Helmet 75, Magic Force Field 120 M.D.C. TW Stake Driver; two silver-plated throwing daggers (1D6 S.D.C., +2 to strike thrown); a dozen stakes and a mallet; a large Wilk''s laser flashlight; high-powered binoculars; survival kit; Robot Medical Kit; IRMSS; Vibro-Knife (1D6 M.D.); a large silver cross. Can draw on the A.M.C. armory and the A.W.M. catalog.', NULL, 'A young-seeming, eager hero who wants to bring his family honor and keep Arzno and its neighbors safe. Hates vampires and the Splugorth without being a zealot, guards his friends fiercely, knows he is no tactician and leans on his officers for that, and is happiest fighting hand to hand, above all against the undead.', 'The Arzno Mercenary Corps and its captains; the people of Arzno.', 'Vampires, Xavier Stuart''s legions in particular (whom he does not yet know of); the Splugorth.', 'Younger son of the ruling family of House Libson, clan Bagh-Dach, whose father rules on a distant world. He wandered the Megaverse as a hero before settling at Arzno, where he commands the Mercenary Corps, dreams of a last stand there against the undead, and quietly readies the city for a vampire army he suspects is gathering to the south. Tall, broad and always immaculate in dress and kit. (p.69-70)', 'Rifts World Book 28: Arzno - Vampire Incursion p.69-70'),
('sgt-samantha', 'Sgt. Samantha', 'Samantha', 'Sergeant of the Arzno Mercenary Corps', 'rifts', 'Were-Jaguar', '5th level Were-Jaguar', 5, 'Unprincipled', '33', NULL, NULL, '{"IQ":9,"ME":11,"MA":13,"PS":20,"PP":21,"PE":19,"PB":13,"Spd":28}', 54, NULL, NULL, 70, 23, NULL, 12, '{"attacks":5,"initiative":1,"strike":5,"parry":5,"dodge":5,"pull":1,"roll":2,"damage":5}', '5 attacks per melee in natural or jaguar form, 3 in human form. Horror Factor 12 in animal form only. +2 to save vs psionics, +2 vs possession, +8% to save vs coma/death, impervious to poisons and toxins, +4 vs magic, +6 vs Horror Factor. The damage bonus applies to every S.D.C. attack. S.D.C.: not applicable. Female.', '[{"name":"Acrobatics","pct":90},{"name":"Camouflage","pct":55},{"name":"Climbing","pct":95},{"name":"Detect Ambush","pct":55},{"name":"Detect Concealment","pct":50},{"name":"Language: Spanish","pct":98},{"name":"Language: American","pct":98},{"name":"Language: Dragonese/Elven","pct":82},{"name":"Language: Gobblely","pct":82},{"name":"Land Navigation","pct":72},{"name":"Lore: Demons & Monsters","pct":45},{"name":"Lore: Magic","pct":45},{"name":"Prowl","pct":72},{"name":"Swimming","pct":80},{"name":"Mathematics: Basic","pct":80},{"name":"Track & Trap Animals","pct":55},{"name":"Tracking","pct":50},{"name":"Wilderness Survival","pct":70}]', 'Hunting, W.P. Knife and W.P. Targeting. Climbing is printed 95%/85% and Track & Trap Animals 55%/65%.', 'Shape-changer at will, day or night, with no limit on how often or how long: human, jaguar, or her natural half-woman, half-jaguar shape. Speaks in animal shape; leaps 30 feet (9.1 m) high or across from a standstill; tracks by smell at 60% (+10% on a blood scent); sees in the dark to 300 feet (91.5 m); sharp hearing and color sight; regenerates 2D6 Hit Points per hour; most weapons cannot harm her, only silver and magic. Rifts World Book 1: Vampire Kingdoms and Rifts Dark Conversions hold the full were-beast rules.', 'Spell Strength 12. Tongues (12), Chameleon (6), Astral Projection (10), Repel Animals (7), Heal Wounds (10), Metamorphosis: Animal (25), Metamorphosis: Human (40).', 'Minor psychic; needs a 12 to save vs psionics. Mind Block (4), See the Invisible (4), Sixth Sense (2).', NULL, 'None. Not compatible.', 'Seldom fights with a weapon and owns few; keeps six silver throwing knives for the undead. Body armor: none. Vehicle: none. Other gear kept to a minimum.', NULL, 'A gifted fighter and hunter the troops treat as one of their own. Years on, she is still uneasy about being a were-beast and feels like an outsider, yet she has become a leader the corps cannot do without. Despises vampires, zombies, the animated dead, demons and most supernatural evil.', 'The Arzno Mercenary Corps.', 'Vampires, zombies, animated dead, demons and most supernatural evil.', 'A were-jaguar sergeant of the Mercenary Corps who stays in human form around others but takes her half-jaguar shape whenever she hunts or fights. (p.73-74)', 'Rifts World Book 28: Arzno - Vampire Incursion p.73-74'),
('xavier-stuart', 'Xavier Stuart', 'Xavier David Stuart', 'General of the vampire legions at Fort Tombstone', 'rifts', 'Master Vampire (was human)', '7th level Master Vampire, was a 6th level CS Military Specialist', 7, 'Diabolic', '46', '5 feet, 10 inches (1.78 m)', '160 lbs (72 kg)', '{"IQ":22,"ME":22,"MA":20,"PS":31,"PP":25,"PE":21,"PB":19,"Spd":28}', 140, NULL, NULL, 30, 160, NULL, 14, '{"attacks":8,"initiative":3,"strike":5,"parry":5,"dodge":5,"damage":16}', 'Supernatural P.S. and P.E. Combat training: supernatural and instinctive. +4 to save vs psionics/insanity, +3 vs magic, +5 vs Horror Factor; impervious to every form of mind control and to psionic and magic sleep and paralysis; 60% trust/intimidate, 45% charm/impress. Skill figures already include +8% to all skills. S.D.C.: not applicable. Male.', '[{"name":"Language: American","pct":98},{"name":"Literacy: American","pct":68},{"name":"Computer Operation","pct":68},{"name":"Electronic Countermeasures","pct":58},{"name":"Intelligence","pct":56},{"name":"Pilot: Automobile","pct":76},{"name":"Pilot: Hover Craft (Ground)","pct":78},{"name":"Pilot: Robots & Power Armor","pct":76},{"name":"Mathematics: Basic","pct":73},{"name":"Radio: Basic","pct":73},{"name":"Weapon Systems","pct":68},{"name":"Detect Ambush","pct":58},{"name":"Detect Concealment","pct":53},{"name":"Interrogation","pct":58},{"name":"Undercover Ops","pct":58},{"name":"Wilderness Survival","pct":58},{"name":"Camouflage","pct":48},{"name":"Demolitions","pct":80},{"name":"Military Etiquette","pct":63},{"name":"Military Fortification","pct":58},{"name":"Sensory Equipment","pct":58},{"name":"Language: Spanish","pct":64},{"name":"Literacy: Spanish","pct":48},{"name":"Climbing","pct":68},{"name":"First Aid","pct":73},{"name":"Surveillance","pct":43}]', 'Robot Combat: Basic, Running, Hand to Hand: Expert, Athletics (General), Body Building & Weight Lifting. W.P. Energy Pistol, W.P. Energy Rifle, W.P. Handguns, W.P. Rifles, W.P. Knife. Climbing is printed 68%/58%. The book notes that some physical skills and the Hand to Hand skill no longer apply now that he is a vampire.', 'Master vampire: limited metamorphosis into wolf, bat or mist; super-regeneration of 2D6 Hit Points per melee, regrowing lost limbs and body parts; limited invulnerability; smells blood a mile (1.6 km) off; nightvision 1,600 feet (488 m); needs no air; summons rodents and canines. Rifts World Book 1: Vampire Kingdoms has the full vampire rules.', 'None.', 'Master psychic; needs a 10 to save vs psionic attack. Alter Aura (2), Empathy (4), Mind Block (2), Presence Sense (4), Hypnotic Suggestion (6), Super Hypnotic Suggestion (20). Each psionic action counts as two hand to hand attacks.', NULL, 'None, not compatible.', 'Rarely armed and rarely fights in person, but favors old CS weapons from his large hoard: C-27 Heavy Plasma Cannon (6D6 M.D.), C-12 Heavy Assault Laser Rifle (2D6 M.D. or a 6D6 M.D. burst), C-18 Laser Pistol (2D4 M.D.), Vibro-Sword (2D6 M.D.), and twin silver-plated daggers. Carries a satchel of at least 20 spare E-Clips into a fight. Body armor: an undamaged CA-4 "Standard" Dead Boy Armor, usually only its chest and arm sections (Main Body 100, Arms 60 each). Vehicle: a Black Market copy of the CS AFC-101 Command Car (180 Main Body M.D.C., 200 mph (320 km), a C-30R Light Rail Gun on the back for 6D6 M.D.); see Rifts World Book 11: Coalition War Campaign p.164.', 'Three million Universal Credits and a million in gems and other valuables at hand; another 20 to 25 million in armor and weapons hidden in a treasure trove in the mines, at a second sanctum no one knows of.', 'A born commander: cold, calculating and brilliant at leading and at tactics, eager to prove himself, savage and merciless to anyone who blocks or defies him. He forgets nothing and forgives no failure however small, and expects every Secondary Vampire he has made to strive for perfection and victory.', 'The Vampire Intelligence that made him its General; Cana the Blind (his seer and slave); High Father Suthue and the Blood Cult.', 'The Coalition States and all of humanity; Prince Onra and the Arzno Mercenary Corps.', 'A Chi-Town ''Burbs orphan who enlisted at sixteen, made officer, and spent decades passed over for command and citizenship. He quit the CS in bitterness, and while working as a farmhand south of Amarillo struck a bargain with a Vampire Intelligence, which made him a Master Vampire and its General for the conquest of the continent. Short, lean and muscular, pale and handsome, with light brown hair and cold blue eyes that turn glowing red when he is angry. (p.134-136)', 'Rifts World Book 28: Arzno - Vampire Incursion p.134-136'),
('cana-the-blind', 'Cana the Blind', 'Cana', 'Xavier''s Advisor', 'rifts', 'Human', '9th level Grey Seer', 9, 'Miscreant', '53, but acts 83', '5 feet, 8 inches (1.73 m)', '140 lbs (63 kg)', '{"IQ":24,"ME":17,"MA":10,"PS":8,"PP":7,"PE":10,"PB":8,"Spd":12}', 43, 39, NULL, 98, 71, NULL, NULL, '{"attacks":3,"initiative":2,"strike":-2,"dodge":2,"pull":1,"roll":-1,"disarm":2}', 'Combat training: none. 3 attacks per melee, or 6 non-combat actions. Automatic dodge; no automatic parry and no special hand to hand attacks. +3 to save vs psionics, +1 vs insanity, +2 vs possession, +3 vs magic, +3 vs Horror Factor. Skill figures already include +10% to all skills. Insanity: overconfident in his own conclusions (and seldom wrong); obsession with a dark future for himself and others. Male.', '[{"name":"Language: American","pct":98},{"name":"Language: Dragonese/Elven","pct":98},{"name":"Literacy: American","pct":98},{"name":"Mathematics: Basic","pct":98},{"name":"Mathematics: Advanced","pct":98},{"name":"Lore: Demons & Monsters","pct":85},{"name":"Lore: Magic","pct":85},{"name":"Wilderness Survival","pct":90},{"name":"Land Navigation","pct":88},{"name":"Astrology","pct":54},{"name":"Astronomy & Navigation","pct":95},{"name":"Language: Spanish","pct":98},{"name":"Literacy: Dragonese/Elven","pct":95},{"name":"Literacy: Spanish","pct":95},{"name":"Philosophy","pct":80},{"name":"Cook","pct":75},{"name":"Barter","pct":52},{"name":"Brewing","pct":40},{"name":"Begging","pct":64},{"name":"Dowsing","pct":70},{"name":"Fasting","pct":74},{"name":"Identify Plants & Fruit","pct":65},{"name":"Sewing","pct":65},{"name":"Preserve Food","pct":40}]', 'W.P. Blunt. Brewing is printed 40%/35%.', 'Grey Seer powers. Senses supernatural evil within 390 feet (119 m). In a trance he is invisible to the supernatural (98%), and if found he is +8 to save vs psionic attack and +4 vs magic. Sense Death, no I.S.P.: tells whether a person has killed, has blood on their hands, or enjoys it; feels vampires within 20 feet (6.1 m), and within 300 feet (91.4 m) the animated dead, zombies, ghouls, mummies and banshees, without numbers or exact place. Sense Life, no I.S.P.: feels supernatural good within 300 feet (91.4 m) and great good in a person he is close to. See Future Possibilities, no I.S.P.: vague glimpses of what lies ahead for a person, and a feeling for a coming confrontation if not its outcome. Vulnerability: combat penalties from his low P.P. and his fatalism.', 'Spell Strength 14. Level 1: Globe of Daylight (2). Level 2: Befuddle (6), Cloak of Darkness (6), Fear (5), Life Source (2+), Magic Shield (6), Manipulate Objects (2+). Level 3: Armor of Ithan (10), Light Healing (6), Light Target (6), Wave of Frost (6). Level 4: Deflect (10), Reflection (7), Weight of Duty (10). Level 5: Aura of Death (12), Death Curse (Special), Horror (10), House of Glass (12), Instill Knowledge (15), Mend the Broken (10+), Mental Blast (15), Sustain (12). Level 6: Tongues (12). Level 8: Oracle (30).', 'Master psychic; needs a 10 to save vs psionics. Sensitive: Clairvoyance (4), Empathy (4), Mind Block (4), Object Read (6), Presence Sense (4), Read Dimensional Portal (6), Remote Viewing (10), See Aura (6), See the Invisible (4), Sense Magic (3), Sixth Sense (2), Telepathy (4), Psionic Invisibility (10).', NULL, 'None. Would accept them only for medical reasons, and then Bio-Systems.', 'None; he is forbidden weapons and has little idea how to use one, so he fights with magic and psionics. Body armor: may wear dinosaur-hide or other natural armor, and sometimes captured Light TW Body Armor when danger is near; full enclosing armor, metal or high-tech, hampers his spell casting. No possessions of note. Vehicle: none; travels with Xavier.', 'None; he is the Master Vampire''s property.', 'A pacifist and pessimist who takes every disaster as the destiny he expected. His intellect and paranormal gifts make his forecasts uncanny, and he shapes much of Xavier''s strategy unseen and unthanked. He hates Xavier but his nature will not let him oppose or disobey him. Frail and old before his time.', 'Xavier Stuart, unwillingly.', 'Xavier Stuart, whom he hates and will never defy.', 'A gifted Mystic from youth who came to see his foresight as a curse. Fellow monks at a small Colorado monastery named him the Blind for his bleak outlook; after seven years he was sent away, drifted south, and was taken in a raid by Xavier''s horde near the Rio Grande. He submitted without a fight, read Xavier''s past at a glance, and has been the General''s seer ever since. Short, thin and stooped, balding, with grey eyes so pale they look white. (p.136-137)', 'Rifts World Book 28: Arzno - Vampire Incursion p.136-137'),
('high-father-suthue', 'High Father Suthue', NULL, 'Blood Priest of the Tombstone Kingdom', 'rifts', 'Unknown', '14th level Blood Priest, was a 12th level spell caster', 14, 'Diabolic', '278; unlikely to live past 300', '6 feet, 10 inches (2 m)', '380 lbs (171 kg)', '{"IQ":12,"ME":10,"MA":25,"PS":20,"PP":8,"PE":20,"PB":5,"Spd":11}', NULL, NULL, 110, 340, NULL, NULL, 13, '{"attacks":7,"strike":2,"parry":3,"dodge":3,"pull":4,"roll":4,"damage":9,"disarm":1}', 'Hand to Hand: Basic. Supernatural P.S. and P.E.; his physical attributes are in decline, P.P. and Spd most of all. Critical strike on an unmodified 19 or 20, body flip/throw, critical strike or knockout from behind. The damage bonus is added to S.D.C. attacks. Impervious to possession and mind control; +2 to save vs psionics, +10% to save vs coma/death, +7 vs magic, +3 vs poison, +6 vs Horror Factor, +4 on all Perception Rolls; 84% trust/intimidate. Hit Points and S.D.C.: not applicable. Real name and race: unknown, as printed. The book''s stat heading calls him Lord Suthue. Male.', '[{"name":"Holistic Medicine","pct":85},{"name":"Identify Plants & Fruits","pct":80},{"name":"Intelligence","pct":74},{"name":"Lore: Geomancy & Ley Lines","pct":90},{"name":"Use & Recognize Poison","pct":72},{"name":"Language: Gobblely","pct":95},{"name":"History (his home world)","pct":70},{"name":"Streetwise","pct":30},{"name":"Writing","pct":70},{"name":"Language: Native Tongue","pct":98},{"name":"Language: Dragonese/Elven","pct":98},{"name":"Language: Demongogian","pct":98},{"name":"Literacy: Native Language","pct":98},{"name":"Literacy: Dragonese/Elven","pct":98},{"name":"Astronomy & Navigation","pct":98},{"name":"Mathematics: Basic","pct":98},{"name":"Lore: Demons & Monsters","pct":98},{"name":"Lore: Magic","pct":98},{"name":"Horsemanship: Exotic Animals","pct":98},{"name":"Lore: Religion","pct":98},{"name":"Performance","pct":98},{"name":"Public Speaking","pct":98},{"name":"Interrogation","pct":85},{"name":"Language: American","pct":69},{"name":"Land Navigation","pct":88},{"name":"Lore: Faeries & Creatures of Magic","pct":90},{"name":"Mathematics: Advanced","pct":98},{"name":"Wilderness Survival","pct":95},{"name":"Skin & Prepare Animal Hides","pct":85},{"name":"Pilot: Hover Craft (Ground)","pct":90},{"name":"Radio: Basic","pct":65},{"name":"Language: Spanish","pct":50}]', 'Holistic Medicine through Writing are his wizard skills, frozen at that level; he also speaks and reads several alien languages, and has W.P. Blunt and W.P. Shield at 6th level. W.P. Knife and W.P. Staff. Holistic Medicine is printed 85%/75% and Use & Recognize Poison 72%/64%.', 'Mega-Damage being with damage resistance, Supernatural Strength and Endurance, an evil presence and long life, plus the spell knowledge every Blood Priest has (the Blood Priest O.C.C., p.142-144). Keeps his wizard''s abilities, frozen at 12th level, among them the Ley Line Walker''s ley line sight and use, drifting and rejuvenation, recognize enchantment (90%) and recognize magic (75%). Vulnerabilities: as for the Blood Priest O.C.C.', 'Spell Strength 16. Every incantation of levels 1-10, plus the Blood Priest''s special spell abilities. Level 11: Create Mummy (160), Remove Curse (140), Re-Open Gateway (180), Rift Teleportation (200). Level 12: Create Zombie (250), Ensorcel (400), Metamorphosis: Mist (250), Soultwist (170), Summon & Control Entity (250). Level 13: Protection Circle: Superior (300), Sanctum (390), Summon Lesser Being (425), Talisman (500). Level 14: Close Rift (200+). Level 15: Ley Line Restoration (800), Summon Ally (600), Transformation (2000). Spells of Legend: Blood and Thunder (770).', 'None.', NULL, 'None; augmentation interferes with magic.', 'Scorns modern weapons and owns no special ones. Carries a large enchanted stone sacrificial knife (2D6+3 S.D.C.), very durable, that can parry magic and Mega-Damage weapons. Body armor: none; his favorite magical protection is Armor Bizarre (180 M.D.C., Rifts Book of Magic p.104). Dresses in long hooded robes, black or deep blue. His cult keeps caches that can arm and armor 25 men at once and 100 cultists within hours, besides what Xavier provides. Vehicle: driven in an armored hover vehicle, such as a command car or hover truck, when he travels by mundane means.', NULL, 'A cruel, violent tyrant given to torture and abuse, wholly devoted to the Vampire Intelligence and to Xavier Stuart because he craves the immortality of a Master Vampire. His sanity is fraying; if he comes to believe that reward will never come, he could turn on Xavier, Xavier''s inner circle, or the Intelligence itself.', 'The Vampire Intelligence; Xavier Stuart; the Blood Cult.', 'Any younger Blood Priest who might replace him; the Secondary Vampires who mock Blood Priests.', 'The Vampire Intelligence''s Supreme Blood Priest, a horned, grey-skinned D-Bee of unknown race whose glassy black eyes and broken fangs lead many to take him for a sub-demon. Once a tyrant worshipped as a dark god on a magic-rich world without technology, he has served the Intelligence for over 150 years, helped it take three worlds, and now gathers a Blood Cult for Xavier at Fort Tombstone. He is starting to age, hides it, and fears being cast aside or made a lesser vampire before he is promised mastery. (p.145-146)', 'Rifts World Book 28: Arzno - Vampire Incursion p.145-146');
